import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.CcKC9xfe.js";const u=JSON.parse('{"title":"Auth Policy Server Integration","description":"yarilo-auth can POST every login attempt to an external HTTP policy service that decides whether to allow, reject, or tarpit the request. The wire shape…","frontmatter":{"outline":[2,4],"head":[["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/auth/policy.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/latest/auth/policy.html"}],["meta",{"property":"og:title","content":"Auth Policy Server Integration"}],["meta",{"name":"twitter:title","content":"Auth Policy Server Integration"}],["meta",{"property":"og:description","content":"yarilo-auth can POST every login attempt to an external HTTP policy service that decides whether to allow, reject, or tarpit the request. The wire shape…"}],["meta",{"name":"twitter:description","content":"yarilo-auth can POST every login attempt to an external HTTP policy service that decides whether to allow, reject, or tarpit the request. The wire shape…"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/latest/auth/policy.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/latest/auth/policy.html\\",\\"headline\\":\\"Auth Policy Server Integration\\",\\"description\\":\\"yarilo-auth can POST every login attempt to an external HTTP policy service that decides whether to allow, reject, or tarpit the request. The wire shape…\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/latest/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Auth Policy Server Integration\\",\\"item\\":\\"https://doc.yarilomail.org/latest/auth/policy.html\\"}]}]}"]]},"headers":[],"relativePath":"auth/policy.md","filePath":"auth/policy.md","lastUpdated":1793450621000}'),o={name:"auth/policy.md"};function d(l,e,r,n,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="auth-policy-server-integration" tabindex="-1">Auth Policy Server Integration <a class="header-anchor" href="#auth-policy-server-integration" aria-label="Permalink to &quot;Auth Policy Server Integration&quot;">​</a></h1><p><code>yarilo-auth</code> can POST every login attempt to an external HTTP policy service that decides whether to allow, reject, or tarpit the request. The wire shape follows the <strong>wforce</strong> (<a href="https://github.com/PowerDNS/weakforced" target="_blank" rel="noreferrer nofollow">weakforced</a>) HTTP API so any policy server speaking that dialect plugs in without a custom adapter.</p><h2 id="when-to-enable" tabindex="-1">When to enable <a class="header-anchor" href="#when-to-enable" aria-label="Permalink to &quot;When to enable&quot;">​</a></h2><p>A policy server is useful when:</p><ul><li>credential-stuffing detection needs cross-IP pattern analysis (one IP brute-forcing 1000 distinct users - invisible to per-IP penalty)</li><li>access policies depend on signals that don&#39;t fit a SQL passdb: geolocation, time of day, fraud-score, SIEM integration</li><li>multi-tenant deployments need per-tenant abuse policies</li><li>compliance requires policy decisions in an audit pipeline</li></ul><p>When the deployment is small and the threat model is satisfied by in-process <code>auth_<wbr>failure_<wbr>delay</code> + <code>auth_<wbr>penalty</code> + per-user@IP connection limits, the policy hook is overkill.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p><code>auth.<wbr>policy</code> in <code>yarilo.<wbr>yaml</code> (the Helm names are <a href="#helm">below</a>):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_server_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://wforce.internal:8084/?ctx=imap&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_server_api_header</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;X-API-Key: change-me&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_hash_mech</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sha256</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_hash_nonce</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deployment-specific-salt-please-rotate&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_hash_truncate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    timeout_ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_reject_on_fail</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_log_only</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_check_before_auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_check_after_auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_report_after_auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h3 id="auth.policy.auth_policy_server_url" tabindex="-1"><code>auth_<wbr>policy_<wbr>server_<wbr>url</code> <a class="header-anchor" href="#auth.policy.auth_policy_server_url" aria-label="Permalink to &quot;\`auth_policy_server_url\` {#auth.policy.auth_policy_server_url}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Also accepted as</dt><dd><code>url</code></dd><dt>Helm</dt><dd><code>components.auth.policy.url</code></dd></dl></div><p>The policy server. Empty disables the hook. A URL ending in <code>&amp;</code> extends its query string instead of starting a new one (<code>https:/<wbr>/<wbr>w/<wbr>?tenant=42&amp;</code>).</p><h3 id="auth.policy.auth_policy_server_api_header" tabindex="-1"><code>auth_<wbr>policy_<wbr>server_<wbr>api_<wbr>header</code> <a class="header-anchor" href="#auth.policy.auth_policy_server_api_header" aria-label="Permalink to &quot;\`auth_policy_server_api_header\` {#auth.policy.auth_policy_server_api_header}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Also accepted as</dt><dd><code>api_header</code></dd><dt>Helm</dt><dd><code>components.auth.policy.api_header</code></dd><dt>See also</dt><dd><a href="/latest/auth/policy.html#components.auth.policy.api_header_secret_ref"><code>api_header_secret_ref</code></a></dd></dl></div><p><code>&quot;Key: value&quot;</code> sends a header of your own; <code>&quot;value&quot;</code> sends <code>X-API-Key: value</code>. <code>\${ENV}</code> is expanded.</p><h3 id="auth.policy.auth_policy_hash_mech" tabindex="-1"><code>auth_<wbr>policy_<wbr>hash_<wbr>mech</code> <a class="header-anchor" href="#auth.policy.auth_policy_hash_mech" aria-label="Permalink to &quot;\`auth_policy_hash_mech\` {#auth.policy.auth_policy_hash_mech}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>sha256</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>sha256</code> <code>sha512</code></dd><dt>Also accepted as</dt><dd><code>hash_mech</code></dd><dt>Helm</dt><dd><code>components.auth.policy.hash_mech</code></dd></dl></div><p>Digest of <code>pwhash</code>. It must match the policy server&#39;s setting.</p><h3 id="auth.policy.auth_policy_hash_nonce" tabindex="-1"><code>auth_<wbr>policy_<wbr>hash_<wbr>nonce</code> <a class="header-anchor" href="#auth.policy.auth_policy_hash_nonce" aria-label="Permalink to &quot;\`auth_policy_hash_nonce\` {#auth.policy.auth_policy_hash_nonce}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Also accepted as</dt><dd><code>hash_nonce</code></dd><dt>Helm</dt><dd><code>components.auth.policy.hash_nonce</code></dd><dt>See also</dt><dd><a href="/latest/auth/policy.html#components.auth.policy.hash_nonce_secret_ref"><code>hash_nonce_secret_ref</code></a></dd></dl></div><p>Salt mixed into <code>pwhash</code>, <strong>required when a policy server is set</strong>. Two deployments with different nonces have different hash spaces. <code>\${ENV}</code> is expanded.</p><h3 id="auth.policy.auth_policy_hash_truncate" tabindex="-1"><code>auth_<wbr>policy_<wbr>hash_<wbr>truncate</code> <a class="header-anchor" href="#auth.policy.auth_policy_hash_truncate" aria-label="Permalink to &quot;\`auth_policy_hash_truncate\` {#auth.policy.auth_policy_hash_truncate}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>12</code></dd><dt>Type</dt><dd>integer, bits</dd><dt>Also accepted as</dt><dd><code>hash_truncate_bits</code></dd><dt>Helm</dt><dd><code>components.auth.policy.hash_truncate_bits</code></dd></dl></div><p>Top bits of the digest that are sent. <code>12</code> gives 4096 buckets, enough for rate-limit patterns and useless for password recovery. <code>0</code> sends the full digest.</p><h3 id="auth.policy.timeout_ms" tabindex="-1"><code>timeout_<wbr>ms</code> <a class="header-anchor" href="#auth.policy.timeout_ms" aria-label="Permalink to &quot;\`timeout_ms\` {#auth.policy.timeout_ms}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>5000</code></dd><dt>Type</dt><dd>integer, milliseconds</dd><dt>Helm</dt><dd><code>components.auth.policy.timeout_ms</code></dd></dl></div><p>Cap on one round trip to the policy server.</p><h3 id="auth.policy.auth_policy_reject_on_fail" tabindex="-1"><code>auth_<wbr>policy_<wbr>reject_<wbr>on_<wbr>fail</code> <a class="header-anchor" href="#auth.policy.auth_policy_reject_on_fail" aria-label="Permalink to &quot;\`auth_policy_reject_on_fail\` {#auth.policy.auth_policy_reject_on_fail}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Also accepted as</dt><dd><code>reject_on_fail</code></dd><dt>Helm</dt><dd><code>components.auth.policy.reject_on_fail</code></dd></dl></div><p><code>true</code> rejects the login when the policy server is unreachable or answers something malformed. <code>false</code> carries on without its guidance.</p><h3 id="auth.policy.auth_policy_log_only" tabindex="-1"><code>auth_<wbr>policy_<wbr>log_<wbr>only</code> <a class="header-anchor" href="#auth.policy.auth_policy_log_only" aria-label="Permalink to &quot;\`auth_policy_log_only\` {#auth.policy.auth_policy_log_only}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Also accepted as</dt><dd><code>log_only</code></dd><dt>Helm</dt><dd><code>components.auth.policy.log_only</code></dd><dt>Changed 2.4.5</dt><dd>A tarpit, and a refusal from <code>auth_policy_reject_on_fail</code>, are no longer applied in log-only mode.</dd></dl></div><p>Ask the policy server and log its verdicts without enforcing them, to roll out a new policy in shadow mode: no tarpit, no refusal, and no refusal from <code>auth_<wbr>policy_<wbr>reject_<wbr>on_<wbr>fail</code> when the server fails.</p><h3 id="auth.policy.auth_policy_check_before_auth" tabindex="-1"><code>auth_<wbr>policy_<wbr>check_<wbr>before_<wbr>auth</code> <a class="header-anchor" href="#auth.policy.auth_policy_check_before_auth" aria-label="Permalink to &quot;\`auth_policy_check_before_auth\` {#auth.policy.auth_policy_check_before_auth}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Also accepted as</dt><dd><code>check_before</code></dd><dt>Helm</dt><dd><code>components.auth.policy.check_before</code></dd></dl></div><p>Ask <code>?command=allow</code> before the passdb chain runs. A rejection skips the passdb call entirely.</p><h3 id="auth.policy.auth_policy_check_after_auth" tabindex="-1"><code>auth_<wbr>policy_<wbr>check_<wbr>after_<wbr>auth</code> <a class="header-anchor" href="#auth.policy.auth_policy_check_after_auth" aria-label="Permalink to &quot;\`auth_policy_check_after_auth\` {#auth.policy.auth_policy_check_after_auth}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Also accepted as</dt><dd><code>check_after</code></dd><dt>Helm</dt><dd><code>components.auth.policy.check_after</code></dd></dl></div><p>Ask <code>?command=allow</code> once the chain&#39;s result is known. A rejection turns a successful login into a failure (account-takeover detection).</p><h3 id="auth.policy.auth_policy_report_after_auth" tabindex="-1"><code>auth_<wbr>policy_<wbr>report_<wbr>after_<wbr>auth</code> <a class="header-anchor" href="#auth.policy.auth_policy_report_after_auth" aria-label="Permalink to &quot;\`auth_policy_report_after_auth\` {#auth.policy.auth_policy_report_after_auth}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Also accepted as</dt><dd><code>report_after</code></dd><dt>Helm</dt><dd><code>components.auth.policy.report_after</code></dd></dl></div><p>Send <code>?command=report</code> after every decision, without waiting for the answer. It never delays the reply to the client.</p><h3 id="auth.policy.auth_policy_request_attributes" tabindex="-1"><code>auth_<wbr>policy_<wbr>request_<wbr>attributes</code> <a class="header-anchor" href="#auth.policy.auth_policy_request_attributes" aria-label="Permalink to &quot;\`auth_policy_request_attributes\` {#auth.policy.auth_policy_request_attributes}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>device_id: %{client_id}, fail_type: %{fail_type}, login: %{requested_username}, protocol: %{protocol}, pwhash: %{hashed_password}, remote: %{remote_ip}, session_id: %{session}</code></dd><dt>Type</dt><dd>map</dd><dt>Helm</dt><dd><code>components.auth.policy.request_attributes</code></dd><dt>Added</dt><dd>2.4.5</dd></dl></div><p>The request body: a body key to its value template. A key <code>name/<wbr>sub</code> puts <code>sub</code> inside the object <code>name</code>. See <a href="/latest/auth/policy.html#request-body">Request body</a> for the variables. An entry adds or replaces one key; a default key cannot be removed. A template naming an unknown variable or filter, or the <code>env:</code>, <code>process:</code> or <code>system:</code> provider, stops <code>yarilo-auth</code> at start.</p><h3 id="helm" tabindex="-1">Helm <a class="header-anchor" href="#helm" aria-label="Permalink to &quot;Helm&quot;">​</a></h3><p>The chart builds <code>auth.<wbr>policy</code> from <code>components.<wbr>auth.<wbr>policy</code>, with shorter names; each card above names its chart value.</p><p>From 2.4.2 a key under its <code>auth.<wbr>policy</code> name fails the render and names the chart&#39;s, and <code>check_<wbr>before</code>, <code>check_<wbr>after</code> and <code>report_<wbr>after</code> set to <code>false</code> and <code>hash_<wbr>truncate_<wbr>bits: 0</code> reach the config. In 2.4.1 such a key is dropped, the three switches cannot be turned off through the chart (a <code>false</code> is rendered as <code>true</code>), and <code>hash_<wbr>truncate_<wbr>bits: 0</code> is rendered as <code>12</code>.</p><p><code>auth_<wbr>policy_<wbr>server_<wbr>api_<wbr>header</code> and <code>auth_<wbr>policy_<wbr>hash_<wbr>nonce</code> expand <code>\${ENV}</code>, so both can come from a Secret; 2.4.1 and earlier take them literally. Through the chart, name the Secret in <code>*_<wbr>secret_<wbr>ref</code> to keep the value out of the config ConfigMap:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://wforce.internal:8084/</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api_header_secret_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">yarilo-policy</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">api_header</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # the default</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      hash_nonce_secret_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">yarilo-policy</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hash_nonce</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # the default</span></span></code></pre></div><p>The chart renders <code>&quot;\${YARILO_<wbr>AUTH_<wbr>POLICY_<wbr>API_<wbr>HEADER}&quot;</code> and <code>&quot;\${YARILO_<wbr>AUTH_<wbr>POLICY_<wbr>HASH_<wbr>NONCE}&quot;</code> and sets both variables in the <code>yarilo-auth</code> pod from the Secret. Setting a value and its <code>*_<wbr>secret_<wbr>ref</code> together fails the render.</p><h4 id="components.auth.policy.api_header_secret_ref" tabindex="-1"><code>api_<wbr>header_<wbr>secret_<wbr>ref</code> <a class="header-anchor" href="#components.auth.policy.api_header_secret_ref" aria-label="Permalink to &quot;\`api_header_secret_ref\` {#components.auth.policy.api_header_secret_ref}&quot;">​</a></h4><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd><code>name: , key: api_header</code></dd><dt>Type</dt><dd>map</dd><dt>See also</dt><dd><a href="/latest/auth/policy.html#auth.policy.auth_policy_server_api_header"><code>auth_policy_server_api_header</code></a></dd></dl></div><p>A Secret (<code>name</code>, <code>key</code>) holding the API header. The chart renders <code>&quot;\${YARILO_<wbr>AUTH_<wbr>POLICY_<wbr>API_<wbr>HEADER}&quot;</code> and sets the variable in the yarilo-auth pod, so the value stays out of the ConfigMap. Setting it together with <code>api_<wbr>header</code> fails the render.</p><h4 id="components.auth.policy.hash_nonce_secret_ref" tabindex="-1"><code>hash_<wbr>nonce_<wbr>secret_<wbr>ref</code> <a class="header-anchor" href="#components.auth.policy.hash_nonce_secret_ref" aria-label="Permalink to &quot;\`hash_nonce_secret_ref\` {#components.auth.policy.hash_nonce_secret_ref}&quot;">​</a></h4><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd><code>name: , key: hash_nonce</code></dd><dt>Type</dt><dd>map</dd><dt>See also</dt><dd><a href="/latest/auth/policy.html#auth.policy.auth_policy_hash_nonce"><code>auth_policy_hash_nonce</code></a></dd></dl></div><p>A Secret (<code>name</code>, <code>key</code>) holding the nonce. The chart renders <code>&quot;\${YARILO_<wbr>AUTH_<wbr>POLICY_<wbr>HASH_<wbr>NONCE}&quot;</code> and sets the variable in the yarilo-auth pod. Setting it together with <code>hash_<wbr>nonce</code> fails the render.</p><h2 id="wire-shape" tabindex="-1">Wire shape <a class="header-anchor" href="#wire-shape" aria-label="Permalink to &quot;Wire shape&quot;">​</a></h2><p>Every request is <code>POST {url}?command={allow|report}</code> with header <code>Content-Type: application/<wbr>json</code> and a JSON body. Every login is checked, whatever the mechanism: PLAIN, LOGIN, SCRAM-SHA-1 and SCRAM-SHA-256 with or without <code>-PLUS</code>, OAUTHBEARER and XOAUTH2.</p><p>The default body:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;device_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">name</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Thunderbird</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">140.4.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;fail_type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;credentials&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;login&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alice@example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;imap&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pwhash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ae30&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;remote&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;203.0.113.42&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;session_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dGVzdHNlc3Npb24&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tls&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;policy_reject&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>success</code> and <code>policy_<wbr>reject</code> appear only in the check after the login and in <code>report</code> calls.</li><li>Keys are in alphabetical order, so the payload is byte-stable across releases.</li></ul><h3 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h3><p><code>auth_<wbr>policy_<wbr>request_<wbr>attributes</code> sets the body: each key is sent as a string expanded from its template. A key <code>name/<wbr>sub</code> puts <code>sub</code> inside the object <code>name</code>. <code>tls</code>, and <code>success</code> and <code>policy_<wbr>reject</code> where they apply, always follow the attributes.</p><p>An entry adds a key or replaces one; a key of the defaults cannot be removed.</p><p>Add the client&#39;s local address to the defaults:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_request_attributes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      attrs/local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%{local_ip}&quot;</span></span></code></pre></div><p>A key <code>a/<wbr>b/<wbr>c</code> nests as deep as it names: <code>c</code> inside <code>b</code> inside <code>a</code>. A key cannot be both a value and an object.</p><h3 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h3><p>A template is text with <code>%{.<wbr>.<wbr>.<wbr>}</code> expressions. An expression names a variable, then filters joined with <code>|</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    auth_policy_request_attributes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      attrs/domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%{user | domain}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      attrs/client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%{real_remote_ip}:%{real_remote_port}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      attrs/tenant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%{passdb:tenant | default(&#39;none&#39;)}&quot;</span></span></code></pre></div><ul><li><code>%%{</code> is a literal <code>%{</code>. A <code>%</code> before anything else, <code>%%</code> included, is sent as it is.</li><li>Filters take positional and named arguments, as in <code>%{user | substr(0, 4)}</code> and <code>%{user | hash(&#39;sha256&#39;, rounds=2)}</code>. An argument can name a variable.</li><li>The language has arithmetic (<code>%{remote_<wbr>port + 1}</code>), comparisons with <code>if</code> and <code>switch</code>, <code>regexp</code>, hashes, <code>base64</code> and <code>hex</code>, <code>encrypt</code> and <code>decrypt</code>, and dates. <code>default</code> gives a value when the expression before it has none or fails.</li><li><code>regexp</code> and the <code>~</code> comparison use RE2 syntax: no backreferences, no lookaround.</li><li><code>encrypt</code> and <code>decrypt</code> take AES-128, AES-192 or AES-256 in CBC or ECB mode.</li><li>A value is JSON-escaped before it goes into the body. <code>safe</code> sends it unescaped, so a value marked <code>safe</code> must already be valid inside a JSON string.</li></ul><p>A template naming an unknown variable or filter stops <code>yarilo-auth</code> at start with the key and the reason, rather than sending an empty value.</p><h3 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><code>%{requested_<wbr>username}</code></td><td style="text-align:left;">the login name as the client sent it</td></tr><tr><td style="text-align:left;"><code>%{user}</code>, <code>%{owner_<wbr>user}</code></td><td style="text-align:left;">the user; after the login, as the passdb resolved it</td></tr><tr><td style="text-align:left;"><code>%{original_<wbr>user}</code>, <code>%{auth_<wbr>user}</code></td><td style="text-align:left;">the login name, as <code>requested_<wbr>username</code></td></tr><tr><td style="text-align:left;"><code>%{domain_<wbr>first}</code>, <code>%{domain_<wbr>last}</code></td><td style="text-align:left;">the part after the first or the last <code>@</code></td></tr><tr><td style="text-align:left;"><code>%{password}</code></td><td style="text-align:left;">the password in plain text</td></tr><tr><td style="text-align:left;"><code>%{hashed_<wbr>password}</code></td><td style="text-align:left;">the <code>pwhash</code> below</td></tr><tr><td style="text-align:left;"><code>%{protocol}</code></td><td style="text-align:left;"><code>imap</code>, <code>pop3</code>, <code>submission</code>, <code>sieve</code>, <code>lmtp</code>, <code>jmap</code></td></tr><tr><td style="text-align:left;"><code>%{mechanism}</code></td><td style="text-align:left;">the SASL mechanism, as <code>PLAIN</code> or <code>SCRAM-SHA-256</code></td></tr><tr><td style="text-align:left;"><code>%{secured}</code></td><td style="text-align:left;"><code>TLS</code> when the client&#39;s connection is TLS, else empty</td></tr><tr><td style="text-align:left;"><code>%{remote_<wbr>ip}</code>, <code>%{remote_<wbr>port}</code></td><td style="text-align:left;">the client&#39;s address and port</td></tr><tr><td style="text-align:left;"><code>%{local_<wbr>ip}</code>, <code>%{local_<wbr>port}</code></td><td style="text-align:left;">the address and port the client connected to</td></tr><tr><td style="text-align:left;"><code>%{real_<wbr>remote_<wbr>ip}</code>, <code>%{real_<wbr>remote_<wbr>port}</code></td><td style="text-align:left;">the peer&#39;s own address and port</td></tr><tr><td style="text-align:left;"><code>%{real_<wbr>local_<wbr>ip}</code>, <code>%{real_<wbr>local_<wbr>port}</code></td><td style="text-align:left;">the local end of that connection</td></tr><tr><td style="text-align:left;"><code>%{local_<wbr>name}</code></td><td style="text-align:left;">the TLS server name (SNI) the client asked for</td></tr><tr><td style="text-align:left;"><code>%{ssl_<wbr>ja3_<wbr>hash}</code></td><td style="text-align:left;">the JA3 hash of the client&#39;s TLS hello</td></tr><tr><td style="text-align:left;"><code>%{client_<wbr>id}</code></td><td style="text-align:left;">the client&#39;s IMAP <code>ID</code>, see <a href="#client-fields">Client fields</a></td></tr><tr><td style="text-align:left;"><code>%{session}</code></td><td style="text-align:left;">the login&#39;s session ID</td></tr><tr><td style="text-align:left;"><code>%{client_<wbr>pid}</code></td><td style="text-align:left;">the process ID of the login process</td></tr><tr><td style="text-align:left;"><code>%{id}</code></td><td style="text-align:left;">after the login, the position of the passdb that answered, from 1</td></tr><tr><td style="text-align:left;"><code>%{fail_<wbr>type}</code></td><td style="text-align:left;">why a login failed, see <a href="#fail-type">below</a></td></tr><tr><td style="text-align:left;"><code>%{cert}</code>, <code>%{ssl_<wbr>client_<wbr>cert_<wbr>fp}</code>, <code>%{ssl_<wbr>client_<wbr>cert_<wbr>pubkey_<wbr>fp}</code></td><td style="text-align:left;">always empty</td></tr><tr><td style="text-align:left;"><code>%{login_<wbr>user}</code>, <code>%{master_<wbr>user}</code>, <code>%{session_<wbr>pid}</code>, <code>%{home}</code></td><td style="text-align:left;">always empty</td></tr></tbody></table><ul><li>Behind a PROXY header or a trusted proxy (XCLIENT, or the IMAP <code>ID</code> of a login in <code>general.<wbr>xclient.<wbr>trusted_<wbr>nets</code>), <code>remote_<wbr>ip</code> is the client the proxy names and <code>real_<wbr>remote_<wbr>ip</code> is the proxy itself. Without one, the <code>real_</code> variables equal the plain ones.</li><li>A port the login did not learn is <code>0</code>.</li><li><code>%{password}</code> sends the password itself to the policy server. Use <code>%{hashed_<wbr>password}</code> unless the server must see the password.</li><li>The login pods do not ask for a client certificate, so the certificate variables are empty.</li><li>Master logins skip the policy server, and the check runs before any session exists, so the other four are empty.</li></ul><h3 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h3><p>A variable <code>prefix:name</code> is read from a provider:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Provider</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><code>%{passdb:name}</code></td><td style="text-align:left;">a field the passdb returned, empty when it returned none</td></tr><tr><td style="text-align:left;"><code>%{userdb:name}</code></td><td style="text-align:left;">a <code>userdb_</code> field the passdb returned, without the prefix</td></tr><tr><td style="text-align:left;"><code>%{date:name}</code></td><td style="text-align:left;">the date: <code>year</code>, <code>month</code>, <code>day</code></td></tr><tr><td style="text-align:left;"><code>%{time:name}</code></td><td style="text-align:left;">the time: <code>hour</code>, <code>min</code>, <code>sec</code>, <code>us</code>, <code>unix</code></td></tr><tr><td style="text-align:left;"><code>%{generate:name}</code></td><td style="text-align:left;">a new <code>guid</code>, <code>guid128</code> or <code>uuid</code></td></tr></tbody></table><p>The passdb fields exist only after the login; in the check before it they are empty.</p><p><code>env:</code>, <code>process:</code> and <code>system:</code> read <code>yarilo-auth</code>&#39;s own environment and host. They are refused in the request body: a template naming one stops <code>yarilo-auth</code> at start, so a secret of its own never reaches the policy server. <code>event:</code> is not available.</p><h3 id="client-fields" tabindex="-1">Client fields <a class="header-anchor" href="#client-fields" aria-label="Permalink to &quot;Client fields&quot;">​</a></h3><ul><li><code>tls</code> is true when the client&#39;s connection is TLS, implicit or after STARTTLS. JMAP, served over HTTPS only, is always TLS.</li><li><code>session_<wbr>id</code> is the session ID the login process gave the connection.</li><li><code>device_<wbr>id</code> is the IMAP <code>ID</code> the client sent before login, kept only with <code>protocol.<wbr>imap.<wbr>imap_<wbr>id_<wbr>retain</code>. Each pair is quoted, as in <code>&quot;name&quot; &quot;Thunderbird&quot; &quot;version&quot; &quot;140.<wbr>4.<wbr>0&quot;</code>; the login&#39;s own <code>x-</code> keys are left out. Without the setting, and for other protocols, it is empty.</li></ul><h3 id="fail-type" tabindex="-1"><code>fail_<wbr>type</code> <a class="header-anchor" href="#fail-type" aria-label="Permalink to &quot;\`fail_type\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;">empty</td><td style="text-align:left;">the login succeeded, or the call is the check before it</td></tr><tr><td style="text-align:left;"><code>credentials</code></td><td style="text-align:left;">a passdb knew the user and refused the password</td></tr><tr><td style="text-align:left;"><code>account</code></td><td style="text-align:left;">no passdb knew the user</td></tr><tr><td style="text-align:left;"><code>internal</code></td><td style="text-align:left;">a passdb could not answer</td></tr><tr><td style="text-align:left;"><code>policy</code></td><td style="text-align:left;">the policy server refused the login</td></tr></tbody></table><p><code>expired</code> and <code>disabled</code> are valid values for a policy server but are not sent: no passdb reports them.</p><h3 id="pwhash" tabindex="-1"><code>pwhash</code> <a class="header-anchor" href="#pwhash" aria-label="Permalink to &quot;\`pwhash\`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>digest = hash_mech(hash_nonce || requested_username || &quot;\\0&quot; || password)</span></span>
<span class="line"><span>pwhash = hex(truncate_to_top_N_bits(digest))</span></span></code></pre></div><p>A SCRAM login carries no password, so its <code>pwhash</code> is over the user alone.</p><p>With the default 12-bit truncation:</p><ul><li><code>pwhash</code> is 4 hex chars (a leading byte + the top nibble of the second byte, masked off)</li><li>4096 possible distinct values for the entire user base</li><li>a single user&#39;s <code>pwhash</code> is stable across attempts with the same password, changes on password change - rate-limiters can count reused-vs-novel passwords per IP without ever seeing plain text</li></ul><p>If your policy server needs higher precision, set <code>auth_<wbr>policy_<wbr>hash_<wbr>truncate</code> to <code>24</code>, <code>48</code>, or <code>0</code> (full digest). Anything above ~32 bits starts to leak which-user-has-which-password information; pick the smallest value your detection logic tolerates.</p><h3 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;msg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;optional message for the client&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>status == 0</code>: allow.</li><li><code>status &lt; 0</code>: refuse. A <code>msg</code> is shown to the client: IMAP answers <code>NO [AUTHENTICATIONFAILED] &lt;msg&gt;</code>, POP3 <code>-ERR [AUTH] &lt;msg&gt;</code>, Submission <code>535 5.<wbr>7.<wbr>8 &lt;msg&gt;</code> and ManageSieve <code>NO (AUTHENTICATIONFAILED) &quot;&lt;msg&gt;&quot;</code>. Without one, the client gets the usual authentication failure.</li><li><code>status &gt; 0</code>: tarpit, <code>yarilo-auth</code> waits <code>status</code> seconds before the login goes on.</li></ul><p>A 2xx HTTP status with malformed JSON or missing <code>status</code> field is treated as a failover per <code>auth_<wbr>policy_<wbr>reject_<wbr>on_<wbr>fail</code>.</p><h3 id="tarpit" tabindex="-1">Tarpit <a class="header-anchor" href="#tarpit" aria-label="Permalink to &quot;Tarpit&quot;">​</a></h3><p>Only the check before the login tarpits. The check after a successful login can refuse it but never delays it.</p><p>A login process whose peer is in <code>general.<wbr>xclient.<wbr>trusted_<wbr>nets</code> is a proxy in front of yarilo: its logins are not tarpitted and do not count towards the auth penalty.</p><h2 id="master-user-exemption" tabindex="-1">Master-user exemption <a class="header-anchor" href="#master-user-exemption" aria-label="Permalink to &quot;Master-user exemption&quot;">​</a></h2><p>Master-user impersonation (SASL PLAIN with non-empty <code>authzid</code>) <strong>bypasses the policy server entirely.</strong> Admin sessions are not subject to user-facing abuse policy. This matches the policy exemption applied to the cross-pod penalty store.</p><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><p><code>yarilo-auth</code> exports:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Metric</th><th style="text-align:left;">Labels</th></tr></thead><tbody><tr><td style="text-align:left;"><code>yarilo_<wbr>auth_<wbr>policy_<wbr>decisions_<wbr>total</code></td><td style="text-align:left;"><code>check</code> (<code>before</code>, <code>after</code>), <code>result</code> (<code>ok</code>, <code>delayed</code>, <code>refused</code>)</td></tr><tr><td style="text-align:left;"><code>yarilo_<wbr>auth_<wbr>policy_<wbr>errors_<wbr>total</code></td><td style="text-align:left;"><code>check</code></td></tr><tr><td style="text-align:left;"><code>yarilo_<wbr>auth_<wbr>policy_<wbr>tarpit_<wbr>seconds_<wbr>total</code></td><td style="text-align:left;"></td></tr></tbody></table><p>The <code>auth: ok</code> and <code>auth: fail</code> log lines carry <code>policy_<wbr>result</code> and <code>policy_<wbr>penalty</code>, the tarpit seconds, when a check ran.</p><h2 id="wforce" tabindex="-1">wforce <a class="header-anchor" href="#wforce" aria-label="Permalink to &quot;wforce&quot;">​</a></h2><p><a href="/latest/auth/wforce.html">wforce Integration</a> deploys weakforced as the policy server, with a policy against password guessing and the steps to turn it on.</p><h2 id="rollout-strategy" tabindex="-1">Rollout strategy <a class="header-anchor" href="#rollout-strategy" aria-label="Permalink to &quot;Rollout strategy&quot;">​</a></h2><ol><li><strong>Shadow mode</strong> (week 1) - set <code>auth_<wbr>policy_<wbr>log_<wbr>only: true</code>, watch the logs for would-have-rejected events. Logins are neither delayed nor refused. Tune policy server thresholds until false-positive rate is acceptable.</li><li><strong>Soft enforce</strong> (week 2) - flip <code>auth_<wbr>policy_<wbr>log_<wbr>only: false</code>, keep <code>auth_<wbr>policy_<wbr>reject_<wbr>on_<wbr>fail: false</code> (fail-open). A policy server outage does not affect logins.</li><li><strong>Hard enforce</strong> (week 3+) - flip <code>auth_<wbr>policy_<wbr>reject_<wbr>on_<wbr>fail: true</code> once the policy server has proven HA. A policy server outage now blocks logins; pair this with a monitored healthcheck.</li></ol><h2 id="tuning-notes" tabindex="-1">Tuning notes <a class="header-anchor" href="#tuning-notes" aria-label="Permalink to &quot;Tuning notes&quot;">​</a></h2><ul><li><code>auth_<wbr>policy_<wbr>check_<wbr>before_<wbr>auth</code> + <code>auth_<wbr>policy_<wbr>check_<wbr>after_<wbr>auth</code> doubles the per-attempt latency. Most operators disable <code>auth_<wbr>policy_<wbr>check_<wbr>after_<wbr>auth</code> once <code>auth_<wbr>policy_<wbr>check_<wbr>before_<wbr>auth</code> is trusted; <code>auth_<wbr>policy_<wbr>report_<wbr>after_<wbr>auth</code> is fire-and-forget so it doesn&#39;t add perceived latency.</li><li>The HTTP client uses keep-alive - a single yarilo-auth pod reuses connections to the policy server across thousands of requests.</li><li>Set <code>timeout_<wbr>ms</code> shorter than <code>auth.<wbr>auth_<wbr>failure_<wbr>delay</code> so a slow policy server doesn&#39;t push the entire wire response past the client timeout.</li></ul>`,111)])])}const y=t(o,[["render",d]]);export{u as __pageData,y as default};
